/// <summary>
///Warehouse message sent to PE Business events
/// </summary>
[BusinessEvents(classStr(METProcessBOHFileContactClass), 'Warehouse detail send to PE', 'This business event is triggered when warehouse detail is requested', ModuleAxapta::Warehouse)]
public final class METProcessBOHBusinessEvent extends BusinessEventsBase
{
    InventLocationId inventLocationId;
    utcdatetime dateTime;

}

Method.Source:
/// <summary>
/// Constructs a new METProcessBOHFileContactClass business event data contract.
/// </summary>
/// <returns>
/// A new <c>METProcessBOHFileContactClass</c> business event data contract.
/// </returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return METProcessBOHFileContactClass::newFromWarehouse(inventLocationId);
}

/// <summary>
/// Parameter method for inventLocationId
/// </summary>
/// <param name = "_inventLocationId">InventLocationId reference</param>
/// <returns>InventLocationId</returns>
public InventLocationId parmWarehouse(InventLocationId _inventLocationId = inventLocationId)
{
    inventLocationId = _inventLocationId;

    return inventLocationId;
}

//<summary>
//Parm method for datetime
//</summary>
//<param name = "datetime">datetime</param>
//<returns>datetime</returns>
public utcdatetime paramDateTime(utcdatetime _dateTime = dateTime)
{
    dateTime = _dateTime;

    return dateTime;
}

/// <summary>
/// Creates a <c>METProcessBOHBusinessEvent</c> for a <c>InventLocationId</c> record.
/// </summary>
/// <param name = "_inventLocationId"> A warehouse record.</param>
/// <returns>An instance of <c>METProcessBOHBusinessEvent</c>.</returns>
public static METProcessBOHBusinessEvent newFromWarehouse(InventLocationId _inventLocationId)
{
    METProcessBOHBusinessEvent businessEvent = new METProcessBOHBusinessEvent();
    businessEvent.parmWarehouse(_inventLocationId);
    businessEvent.paramDateTime(DateTimeUtil::utcNow());
    info(strFmt('%1,%2',_inventLocationId,DateTimeUtil::utcNow()));

    return businessEvent;
}
